subagents.output_schema_json:
{
  "additionalProperties": false,
  "properties": {
    "budget": {
      "description": "Optional budget/forecast figures keyed by account code",
      "type": "object"
    },
    "current_tb": {
      "description": "Current-period trial balance keyed by account code",
      "type": "object"
    },
    "entity": {
      "maxLength": 128,
      "type": "string"
    },
    "period": {
      "description": "Close period identifier, e.g. 2026-04 or 2026-Q1",
      "maxLength": 32,
      "type": "string"
    },
    "prior_tb": {
      "description": "Prior-period trial balance keyed by account code",
      "type": "object"
    }
  },
  "required": [
    "entity",
    "period",
    "current_tb"
  ],
  "type": "object"
}
